package com.englishhero.vocabulary.learning;
import java.util.*;
import org.springframework.stereotype.Repository;
import static com.englishhero.vocabulary.learning.WordbookDtos.*;
@Repository
public class WordbookMapper {
 private final LearningMapper db;public WordbookMapper(LearningMapper db){this.db=db;}
 public List<Book> books(long user,Long id){String where=id==null?"(b.status='PUBLISHED' OR EXISTS (SELECT 1 FROM vocabulary_learning_session s WHERE s.user_id=? AND s.kind='NEW' AND s.source_key=CONCAT('BOOK:',b.id) AND s.status<>'COMPLETED'))":"b.id=?";var args=new ArrayList<Object>();args.add(user);if(id!=null)args.add(id);else args.add(user);
  return db.jdbc().query("SELECT b.*,(SELECT COUNT(*) FROM vocabulary_wordbook_entry e JOIN vocabulary_learning_word w ON w.entry_id=e.entry_id AND w.user_id=? AND (w.stage>0 OR w.proficient=TRUE) WHERE e.book_id=b.id) learned FROM vocabulary_wordbook b WHERE "+where+" ORDER BY b.id",(r,n)->new Book(r.getString("id"),r.getString("title"),r.getString("data_version"),r.getString("source_url"),r.getString("notice"),r.getInt("original_count"),r.getInt("available_count"),r.getInt("missing_phonetic_count"),List.of(db.decode(r.getString("excluded_json"),Excluded[].class)),r.getString("status"),r.getInt("learned")),args.toArray());
 }
 public Source selected(long user){var ids=db.jdbc().queryForList("SELECT book_id FROM vocabulary_learning_source WHERE user_id=? AND kind='BOOK'",Long.class,user);if(ids.isEmpty())return new Source("PERSONAL",null,"我的阅读生词",true,"",null);var book=books(user,ids.getFirst());if(book.isEmpty())return new Source("BOOK",Long.toString(ids.getFirst()),"原词书",false,"原词书暂不可用，请切换来源",null);var b=book.getFirst();boolean available=b.status().equals("PUBLISHED");return new Source("BOOK",b.id(),b.title(),available,available?"":"该词书已下架，可继续原轮次和到期复习，或切换新词来源",b.availableCount());}
 public int unlearned(long user,Source source){if(!source.available())return 0;if(source.kind().equals("PERSONAL"))return (int)db.count("SELECT COUNT(*) FROM vocabulary_learning_word WHERE user_id=? AND personal_enrolled=TRUE AND active=TRUE AND proficient=FALSE AND stage=0 AND NOT EXISTS (SELECT 1 FROM vocabulary_learning_item i JOIN vocabulary_learning_session s ON s.id=i.session_id WHERE i.learning_word_id=vocabulary_learning_word.id AND s.status<>'COMPLETED' AND s.source_key<>'PERSONAL')",user);
  return (int)db.count("SELECT COUNT(*) FROM vocabulary_wordbook_entry e LEFT JOIN vocabulary_learning_word w ON w.entry_id=e.entry_id AND w.user_id=? WHERE e.book_id=? AND (w.id IS NULL OR (w.active=TRUE AND w.proficient=FALSE AND w.stage=0)) AND NOT EXISTS (SELECT 1 FROM vocabulary_learning_item i JOIN vocabulary_learning_session s ON s.id=i.session_id WHERE i.learning_word_id=w.id AND s.status<>'COMPLETED' AND s.source_key<>?)",user,source.bookId(),LearningService.sourceKey(source));
 }
 // Called only within LearningService.start after the same user's write lock.
 public List<Long> allocate(long user,int limit,Source source){if(source.kind().equals("PERSONAL"))return db.jdbc().queryForList("SELECT id FROM vocabulary_learning_word WHERE user_id=? AND personal_enrolled=TRUE AND active=TRUE AND proficient=FALSE AND stage=0 AND NOT EXISTS (SELECT 1 FROM vocabulary_learning_item i JOIN vocabulary_learning_session s ON s.id=i.session_id WHERE i.learning_word_id=vocabulary_learning_word.id AND s.status<>'COMPLETED') ORDER BY id LIMIT ?",Long.class,user,limit);
  var entries=db.jdbc().queryForList("SELECT e.entry_id FROM vocabulary_wordbook_entry e LEFT JOIN vocabulary_learning_word w ON w.entry_id=e.entry_id AND w.user_id=? WHERE e.book_id=? AND (w.id IS NULL OR (w.active=TRUE AND w.proficient=FALSE AND w.stage=0)) AND NOT EXISTS (SELECT 1 FROM vocabulary_learning_item i JOIN vocabulary_learning_session s ON s.id=i.session_id WHERE i.learning_word_id=w.id AND s.status<>'COMPLETED') ORDER BY e.sort_order LIMIT ?",Long.class,user,source.bookId(),limit);var result=new ArrayList<Long>();for(long entry:entries){db.jdbc().update("INSERT INTO vocabulary_learning_word(user_id,entry_id,personal_enrolled) VALUES(?,?,FALSE) ON DUPLICATE KEY UPDATE id=id",user,entry);result.add(db.jdbc().queryForObject("SELECT id FROM vocabulary_learning_word WHERE user_id=? AND entry_id=?",Long.class,user,entry));}return result;
 }
}
